def _weave(a, b):
    out = []
    n = min(len(a), len(b))
    for i in range(n):
        out.append(a[i])
        out.append(b[i])
    rest = list(a[n:]) if len(a) > len(b) else list(b[n:])
    out.extend(reversed(rest))
    return out


